do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Spanish 2$j$, $j${"questions": [{"q": "Me despierto a las seis means:", "options": ["I wake him at six", "I sleep at six", "I wake up at six", "I eat at six"]}, {"q": "The yo form of hacer in the present is:", "options": ["Hazo", "Hace", "Hago", "Hacio"]}, {"q": "To say you know a person, use:", "options": ["Poder", "Conocer", "Ser", "Saber"]}, {"q": "The yo preterite of buscar is:", "options": ["Buscé", "Buscí", "Busqué", "Busco"]}, {"q": "The preterite of tener for yo is:", "options": ["Tengo", "Tendré", "Tenía", "Tuve"]}, {"q": "Íbamos a la iglesia cada domingo uses the imperfect because it describes:", "options": ["A future plan", "A single event", "A command", "A habit"]}, {"q": "Mientras leía, llegó mi amigo. Llegó is in the:", "options": ["Future", "Imperfect", "Preterite", "Command"]}, {"q": "The pronoun that replaces la Biblia is:", "options": ["Le", "Lo", "La", "Las"]}, {"q": "Le doy el libro becomes:", "options": ["Me lo doy", "Le lo doy", "Se lo doy", "Lo le doy"]}, {"q": "Mi hermano es más alto que yo means:", "options": ["My brother is taller than I am", "I am taller than my brother", "My brother is the tallest", "My brother is as tall as I am"]}, {"q": "Gracias ___ la ayuda.", "options": ["por", "de", "para", "con"]}, {"q": "The usted command of hablar is:", "options": ["Hable", "Hablar", "Hablas", "Habla"]}, {"q": "The affirmative tú command of hacer is:", "options": ["Hazo", "Hagas", "Hace", "Haz"]}, {"q": "Mañana ___ la tarea.", "options": ["hago ayer", "hacía", "haré", "hice"]}, {"q": "Matthew 25:40 teaches us that serving the least of these is like serving:", "options": ["A teacher", "Christ", "A friend only", "Ourselves"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Spanish 2$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,2,3,3,2,2,2,0,0,0,3,2,1}'::int[], array[$j$Despertarse is reflexive and changes e to ie.$j$,$j$Hacer is a yo go verb.$j$,$j$Conocer is for people and places.$j$,$j$Car changes to qué.$j$,$j$Tener has the stem tuv.$j$,$j$The imperfect describes habitual past actions.$j$,$j$A sudden event uses the preterite.$j$,$j$La replaces a feminine singular noun.$j$,$j$Le becomes se before lo.$j$,$j$Más plus an adjective plus que compares.$j$,$j$Por shows the reason for thanks.$j$,$j$Ar verbs take e in the formal command.$j$,$j$Hacer is irregular and becomes haz.$j$,$j$The future of hacer uses the stem har.$j$,$j$Jesus said what we do for the least of these we do for Him.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Spanish 2$j$ on conflict (item_id) do nothing;
end
$seed$;
